steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(identifier: \"ENG-7\") { id identifier title relations { id relationType id1 id2 createdAt } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { identifier: { eq: \"ENG-7\" } }) { nodes { id identifier title relations { edges { node { __typename } } } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(search: \"ENG-7\", first: 5) { nodes { id identifier title } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { number: { eq: 7 } }, first: 10) { nodes { id identifier title } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(id: \"i-eng-7\") { id identifier title relations { edges { node { __typename ... on IssueRelation { id relationType } ... on BlockedByRelation { id relationType } } } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"IssueRelation\") { kind fields { name type { name kind } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(id: \"i-eng-7\") { id identifier title relations { edges { node { __typename ... on IssueRelation { id type createdAt issue { identifier title } relatedIssue { identifier title } } } } } } }"
  }'
